import{_ as o,o as t,c as a,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"Technical Implementation Plan — Mobile Pro VisionCamera Capture, Offline-Resilient S3 Multipart Sync & Task Take Promotion (mobile-creator-upload)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/08-mobile-application/mobile-creator-upload/plan.md","filePath":"feature/modules/08-mobile-application/mobile-creator-upload/plan.md"}'),i={name:"feature/modules/08-mobile-application/mobile-creator-upload/plan.md"};function r(s,e,c,d,l,m){return t(),a("div",null,[...e[0]||(e[0]=[n('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="technical-implementation-plan-—-mobile-pro-visioncamera-capture-offline-resilient-s3-multipart-sync-task-take-promotion-mobile-creator-upload" tabindex="-1">Technical Implementation Plan — Mobile Pro VisionCamera Capture, Offline-Resilient S3 Multipart Sync &amp; Task Take Promotion (<code>mobile-creator-upload</code>) <a class="header-anchor" href="#technical-implementation-plan-—-mobile-pro-visioncamera-capture-offline-resilient-s3-multipart-sync-task-take-promotion-mobile-creator-upload" aria-label="Permalink to &quot;Technical Implementation Plan — Mobile Pro VisionCamera Capture, Offline-Resilient S3 Multipart Sync &amp; Task Take Promotion (`mobile-creator-upload`)&quot;">​</a></h1><h2 id="_1-system-components-touched-repositories" tabindex="-1">1. System Components &amp; Touched Repositories <a class="header-anchor" href="#_1-system-components-touched-repositories" aria-label="Permalink to &quot;1. System Components &amp; Touched Repositories&quot;">​</a></h2><p>Consolidates the technical architecture for <code>mobile-creator-upload</code>, <code>mobile-video-task-sync</code>, <code>mobile-native-enhancements (OfflineBanner &amp; Haptics)</code> as specified in <a href="./spec.html">spec.md</a>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Layer / Repository</th><th style="text-align:left;">Key Classes, Services, Schemas &amp; Components</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway (<code>brandhub-api-gateway</code>)</strong></td><td style="text-align:left;"><code>GatewayConfig.java</code> (<code>/api/v1/workspaces/*/materials/**</code>)</td></tr><tr><td style="text-align:left;"><strong>Backend / Worker Services</strong></td><td style="text-align:left;"><code>MaterialController.java</code>, <code>TaskPostController.java</code>, <code>S3FileStorageServiceImpl.java</code></td></tr><tr><td style="text-align:left;"><strong>Persistence, Cache &amp; Brokers</strong></td><td style="text-align:left;">Device <code>expo-file-system</code> persistent queue; AWS S3; MongoDB <code>materials</code> (<code>taskId</code> linked) &amp; <code>posts</code>; PostgreSQL <code>agency_storage_reservations</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend (<code>brandhub-web</code>)</strong></td><td style="text-align:left;"><code>pages/tasks/detail.tsx</code> (&#39;Mobile Uploads&#39; preview &amp; take promotion section)</td></tr><tr><td style="text-align:left;"><strong>Mobile App (<code>brandhub-mobile-app</code>)</strong></td><td style="text-align:left;"><code>src/screens/content/{CameraRecordScreen,CameraUnavailableScreen,TaskUploadScreen,UploadScreen}.tsx</code>, <code>src/components/camera/*</code>, <code>src/components/common/OfflineBanner.tsx</code>, <code>src/services/{mediaSyncService,uploadService}.ts</code></td></tr><tr><td style="text-align:left;"><strong>i18n &amp; Theme Assets</strong></td><td style="text-align:left;"><code>camera.*</code>, <code>upload.*</code>, <code>offlineBanner.*</code> in <code>src/i18n/locales/en.json</code> &amp; <code>src/i18n/locales/vi/common.json</code> (<code>tr()</code>); Mobile <code>src/i18n/locales/en.json</code> + <code>src/i18n/locales/vi/common.json</code> &amp; <code>src/theme/tokens.ts</code></td></tr></tbody></table><h2 id="_2-core-technical-design-data-model-invariants" tabindex="-1">2. Core Technical Design &amp; Data Model Invariants <a class="header-anchor" href="#_2-core-technical-design-data-model-invariants" aria-label="Permalink to &quot;2. Core Technical Design &amp; Data Model Invariants&quot;">​</a></h2><ul><li><strong>Capability-Driven Camera UI (<code>nativeCameraGuard.ts</code>):</strong> Queries <code>CameraDevice</code> format ranges at runtime so manual ISO/Shutter/WB rails only activate when supported by the physical sensor.</li><li><strong>SHA-256 &amp; Multipart Integrity (<code>sha256.ts</code>):</strong> Streams file chunks from <code>expo-file-system</code> with <code>expo-keep-awake</code> active during large foreground video transfers.</li></ul><h2 id="_3-end-to-end-data-control-flow" tabindex="-1">3. End-to-End Data &amp; Control Flow <a class="header-anchor" href="#_3-end-to-end-data-control-flow" aria-label="Permalink to &quot;3. End-to-End Data &amp; Control Flow&quot;">​</a></h2><ol><li><strong>Ingress &amp; Identity Propagation:</strong> Requests pass through <code>brandhub-api-gateway</code> (<code>InboundSecurityWebFilter</code> -&gt; <code>JwtAuthFilterGatewayFilterFactory</code> -&gt; <code>RateLimitGatewayFilterFactory</code>), stripping external header spoofing and injecting verified <code>X-User-Id</code>, <code>X-Request-Id</code>, and role claims.</li><li><strong>Authorization &amp; Invariant Validation:</strong> Downstream controllers and services re-verify canonical role permissions (<code>Owner, Manager, Creator, Client</code>) and Agency/Workspace tenant membership against authoritative database state before mutating data or dispatching async jobs.</li><li><strong>Atomic Persistence &amp; Event Fan-Out:</strong> State transitions commit atomically across Device <code>expo-file-system</code> persistent queue; AWS S3; MongoDB <code>materials</code> (<code>taskId</code> linked) &amp; <code>posts</code>; PostgreSQL <code>agency_storage_reservations</code> using optimistic (<code>@Version</code> / <code>expectedRevision</code>) or pessimistic locks, emitting outbox/WebSocket/<code>pg_notify</code> events after commit.</li><li><strong>Client State Reconciliation:</strong> <code>brandhub-web</code> and <code>brandhub-mobile-app</code> consume typed <code>ApiResponse&lt;T&gt;</code> envelopes, update user/tenant-scoped <code>TanStack Query</code> caches, and render localized UI states in Light and Dark themes.</li></ol><h2 id="_4-sequential-implementation-rollout-order" tabindex="-1">4. Sequential Implementation &amp; Rollout Order <a class="header-anchor" href="#_4-sequential-implementation-rollout-order" aria-label="Permalink to &quot;4. Sequential Implementation &amp; Rollout Order&quot;">​</a></h2><ol><li><strong>Phase 1 — Database / Storage / Config Baseline:</strong> Apply additive migrations in <code>database/init/init-postgres-v2.sql</code> and <code>database/migrations/postgres/*.sql</code> (plus MongoDB/Neo4j/Redis indexes) with repeat-run idempotency.</li><li><strong>Phase 2 — Domain Services &amp; Security Guards:</strong> Implement core service logic, cryptographic/concurrency helpers, and internal service-to-service contracts.</li><li><strong>Phase 3 — Public REST / WebSocket / Worker Endpoints:</strong> Wire controllers, consumers, and exception handlers returning standardized <code>ErrorCode</code> payloads.</li><li><strong>Phase 4 — Web &amp; Mobile UI Surfaces:</strong> Deliver responsive components, accessibility/keyboard navigation, and state transitions without mock data fallbacks.</li><li><strong>Phase 5 — Key-Parallel i18n (<code>vi</code>/<code>en</code>) &amp; Light/Dark Theme Audit:</strong> Synchronize translation namespaces and verify semantic color tokens across Light and Dark modes.</li><li><strong>Phase 6 — Multi-Layer Verification:</strong> Execute unit, integration, contract, and browser/mobile E2E suites documented in <a href="./test.html">test.md</a>.</li></ol><h2 id="_5-localization-vi-json-en-json-theme-tokens-observability-plan" tabindex="-1">5. Localization (<code>vi.json</code> + <code>en.json</code>), Theme Tokens &amp; Observability Plan <a class="header-anchor" href="#_5-localization-vi-json-en-json-theme-tokens-observability-plan" aria-label="Permalink to &quot;5. Localization (`vi.json` + `en.json`), Theme Tokens &amp; Observability Plan&quot;">​</a></h2><ul><li><strong>Key-Parallel Locale Synchronization:</strong> Every new or updated label in <code>camera.*</code>, <code>upload.*</code>, <code>offlineBanner.*</code> in <code>src/i18n/locales/en.json</code> &amp; <code>src/i18n/locales/vi/common.json</code> (<code>tr()</code>) is committed simultaneously in <code>vi</code> and <code>en</code> bundles on <code>brandhub-web</code> and mirrored in <code>brandhub-mobile-app/src/i18n/locales/en.json</code> + <code>src/i18n/locales/vi/common.json</code> (verified by <code>mobileI18nParity.test.ts</code> and <code>i18nCoverage.test.ts</code>).</li><li><strong>Light &amp; Dark Theme Architecture:</strong> Web components rely exclusively on semantic CSS custom properties (<code>bg-background</code>, <code>bg-card</code>, <code>text-foreground</code>, <code>text-muted-foreground</code>, <code>border-border</code>) and paired <code>dark:</code> utility classes; Mobile components consume <code>useAppPreferences().palette</code> (<code>src/theme/tokens.ts</code>) verified by <code>tokens.test.ts</code>.</li><li><strong>Structured Telemetry &amp; Rollback Safety:</strong> Every boundary logs <code>X-Request-Id</code>, latency, and classified <code>ErrorCode</code> while redacting tokens/PII. Additive schema migrations preserve backward-compatible rollback without dropping historical audit or ledger data.</li></ul><h2 id="_6-engineering-risks-mitigations" tabindex="-1">6. Engineering Risks &amp; Mitigations <a class="header-anchor" href="#_6-engineering-risks-mitigations" aria-label="Permalink to &quot;6. Engineering Risks &amp; Mitigations&quot;">​</a></h2><ul><li><strong>Raw Outtakes Exposed to Client Prematurely:</strong> Enforced server-side in <code>TaskPostService</code> / <code>MaterialService</code> — raw takes remain internal (<code>Owner/Manager/Creator</code>) unless attached to a review-stage post.</li></ul>',15)])])}const u=o(i,[["render",r]]);export{g as __pageData,u as default};
